CREATE TABLE Roles (Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE Users (Id INT IDENTITY PRIMARY KEY, FullName NVARCHAR(120) NOT NULL, Email NVARCHAR(180) NOT NULL UNIQUE, PasswordHash NVARCHAR(MAX) NOT NULL, Phone NVARCHAR(40), RoleId INT NOT NULL REFERENCES Roles(Id));
CREATE TABLE Coffees (Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(120) NOT NULL, Description NVARCHAR(MAX) NOT NULL, Price DECIMAL(10,2) NOT NULL, Category NVARCHAR(80) NOT NULL, SizeOptions NVARCHAR(200) NOT NULL, ImageUrl NVARCHAR(MAX) NOT NULL, Ingredients NVARCHAR(300) NOT NULL, Calories INT NOT NULL, IsFeatured BIT NOT NULL, IsAvailable BIT NOT NULL);
CREATE TABLE Locations (Id INT IDENTITY PRIMARY KEY, Name NVARCHAR(120) NOT NULL, Address NVARCHAR(240) NOT NULL, Phone NVARCHAR(40) NOT NULL, OpeningHours NVARCHAR(80) NOT NULL, Latitude DECIMAL(9,6) NOT NULL, Longitude DECIMAL(9,6) NOT NULL);
CREATE TABLE Orders (Id INT IDENTITY PRIMARY KEY, OrderNumber NVARCHAR(40) NOT NULL, UserId INT NOT NULL REFERENCES Users(Id), LocationId INT NOT NULL REFERENCES Locations(Id), Status NVARCHAR(40) NOT NULL, TotalAmount DECIMAL(10,2) NOT NULL, PickupTime DATETIME2 NOT NULL, CreatedAt DATETIME2 NOT NULL);
CREATE TABLE OrderItems (Id INT IDENTITY PRIMARY KEY, OrderId INT NOT NULL REFERENCES Orders(Id) ON DELETE CASCADE, CoffeeId INT NOT NULL REFERENCES Coffees(Id), Quantity INT NOT NULL, Size NVARCHAR(40) NOT NULL, MilkType NVARCHAR(40) NOT NULL, SugarLevel NVARCHAR(40) NOT NULL, Toppings NVARCHAR(120) NOT NULL, UnitPrice DECIMAL(10,2) NOT NULL);
CREATE TABLE Reviews (Id INT IDENTITY PRIMARY KEY, UserId INT NOT NULL REFERENCES Users(Id), CoffeeId INT NOT NULL REFERENCES Coffees(Id), Rating INT NOT NULL, Comment NVARCHAR(MAX) NOT NULL, CreatedAt DATETIME2 NOT NULL);
